-- Additive management facts; no registrations, qualifications, keys or PUBLIC grants.
SET ROLE hub2_authz_owner;
CREATE TABLE authz.provider_management_registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,area_id uuid,provider_kind text NOT NULL CHECK(provider_kind IN('bao_db_lease','fixed_policy_sts')),revision bigint NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT false,descriptor_hash text NOT NULL CHECK(descriptor_hash~'^[a-f0-9]{64}$'),allowed_steps text[] NOT NULL,consumer_ids text[] NOT NULL CHECK(cardinality(consumer_ids)>0),active_operation_id uuid,active_generation bigint,scope_facts jsonb NOT NULL DEFAULT '{}');
CREATE TABLE authz.provider_management_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,area_id uuid,actor_id uuid NOT NULL,organization_id uuid NOT NULL,original_client_id uuid NOT NULL,registration_id uuid,requested_action text NOT NULL,expected_old_operation_id uuid,expected_old_generation bigint,idempotency_key text NOT NULL,fingerprint text NOT NULL,requested_scope jsonb NOT NULL DEFAULT '{}',consumer_ids text[] NOT NULL DEFAULT '{}',scope_supported boolean NOT NULL DEFAULT false,judgment jsonb NOT NULL DEFAULT '{}',revision bigint NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'planned',generation bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(actor_id,idempotency_key));
CREATE TABLE authz.provider_management_steps(operation_id uuid NOT NULL REFERENCES authz.provider_management_operations,step_no bigint NOT NULL,kind text NOT NULL,state text NOT NULL DEFAULT 'intent'CHECK(state IN('intent','known_succeeded','known_failed','unknown')),execution_token uuid NOT NULL DEFAULT gen_random_uuid(),registration_revision bigint NOT NULL,descriptor_hash text NOT NULL,attempt bigint NOT NULL DEFAULT 1,deadline timestamptz NOT NULL,requested_by_client_id uuid NOT NULL,credential_id uuid NOT NULL,credential_epoch bigint NOT NULL,principal_epoch bigint NOT NULL,client_epoch bigint NOT NULL,family_id uuid,security_era uuid NOT NULL,effect_authorized_at timestamptz,execution_parameters jsonb NOT NULL DEFAULT '{}',receipt jsonb,PRIMARY KEY(operation_id,step_no),UNIQUE(execution_token));
CREATE TABLE authz.credential_generations(operation_id uuid NOT NULL REFERENCES authz.provider_management_operations,generation bigint NOT NULL,registration_id uuid NOT NULL,provider_identity jsonb NOT NULL,secret_ref text NOT NULL,expires_at timestamptz,state text NOT NULL CHECK(state IN('created','staged','active','provider_revoked_verified','expired_verified','platform_denied_only','unknown')),PRIMARY KEY(operation_id,generation));
CREATE TABLE authz.consumer_generation_observations(operation_id uuid NOT NULL REFERENCES authz.provider_management_operations,generation bigint NOT NULL,consumer_id text NOT NULL,state text NOT NULL CHECK(state IN('staged','probed','active_verified')),config_revision text NOT NULL,positive_probe jsonb NOT NULL,cross_scope_probe jsonb NOT NULL,observed_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(operation_id,generation,consumer_id));
REVOKE ALL ON authz.provider_management_registrations,authz.provider_management_operations,authz.provider_management_steps,authz.credential_generations,authz.consumer_generation_observations FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
CREATE FUNCTION authz.provider_management_guard(p_hash text,pid uuid,aid uuid,effect boolean)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE identity jsonb;q record;r jsonb;allowed boolean:=false;until_at timestamptz:='-infinity';path_until timestamptz;ancestor authz.qualifications;
BEGIN
 identity:=authz.provider_catalog_guard62(p_hash,pid,aid,false);IF NOT effect THEN RETURN identity;END IF;
 r:=jsonb_strip_nulls(jsonb_build_object('project_id',pid,'area_id',aid));PERFORM authz.lock_resources((identity->>'actor_id')::uuid,(identity->>'client_id')::uuid,(identity->>'credential_id')::uuid,jsonb_build_array(r));identity:=authz.authenticate(p_hash);
 IF NOT EXISTS(SELECT FROM authz.clients WHERE id=(identity->>'client_id')::uuid AND active AND'credential.manage'=ANY(actions))THEN RAISE EXCEPTION 'credential_manage_ceiling_required' USING ERRCODE='42501';END IF;
 FOR q IN SELECT * FROM authz.qualifications WHERE principal_id=(identity->>'actor_id')::uuid AND project_id=pid AND'credential.manage'=ANY(actions)ORDER BY id LOOP
  IF authz.management_valid(q.id,(identity->>'actor_id')::uuid,pid)AND authz.selector_matches(q.resource_selector,pid,r)THEN allowed:=true;path_until:=CASE WHEN q.until_revoked THEN 'infinity'::timestamptz ELSE q.expires_at END;IF q.parent_id IS NOT NULL THEN SELECT * INTO ancestor FROM authz.qualifications WHERE id=q.parent_id;path_until:=least(path_until,CASE WHEN ancestor.until_revoked THEN 'infinity'::timestamptz ELSE ancestor.expires_at END);END IF;until_at:=greatest(until_at,path_until);END IF;
 END LOOP;
 IF NOT allowed OR until_at<=clock_timestamp()THEN RAISE EXCEPTION 'current_credential_management_scope_required' USING ERRCODE='42501';END IF;
 RETURN identity||jsonb_build_object('management_until',least(until_at,CASE WHEN(identity->>'until_revoked')::boolean THEN'infinity'::timestamptz ELSE(identity->>'expires_at')::timestamptz END,coalesce((SELECT expires_at FROM authz.refresh_families WHERE id=(SELECT family_id FROM authz.credentials WHERE id=(identity->>'credential_id')::uuid)),'infinity'::timestamptz)));
END $$;
CREATE FUNCTION authz.provider_management_view(oid uuid)RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
 SELECT to_jsonb(o)||jsonb_build_object('steps',coalesce((SELECT jsonb_agg(to_jsonb(s)-ARRAY['execution_token','credential_id','credential_epoch','principal_epoch','client_epoch','family_id','security_era','execution_parameters']ORDER BY step_no)FROM authz.provider_management_steps s WHERE operation_id=o.id),'[]'),'generations',coalesce((SELECT jsonb_agg(to_jsonb(g)ORDER BY generation)FROM authz.credential_generations g WHERE operation_id=o.id),'[]'),'consumer_observations',coalesce((SELECT jsonb_agg(to_jsonb(c))FROM authz.consumer_generation_observations c WHERE operation_id=o.id),'[]'),'facts_are_not_execution_permission',true)FROM authz.provider_management_operations o WHERE o.id=oid $$;
CREATE FUNCTION authz.provider_management_scope_supported(rid uuid,scope jsonb,consumers text[])RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE r authz.provider_management_registrations;t numeric;
BEGIN
 SELECT * INTO r FROM authz.provider_management_registrations WHERE id=rid;
 IF r.id IS NULL OR jsonb_typeof(scope)IS DISTINCT FROM'object'OR cardinality(consumers)<1 OR NOT consumers<@r.consumer_ids THEN RETURN false;END IF;
 IF scope?'ttl_seconds'THEN IF jsonb_typeof(scope->'ttl_seconds')IS DISTINCT FROM'number'THEN RETURN false;END IF;t:=(scope->>'ttl_seconds')::numeric;IF t<=0 OR t<>trunc(t)OR t>coalesce((r.scope_facts->>'max_ttl_seconds')::numeric,0)THEN RETURN false;END IF;END IF;
 IF r.provider_kind='bao_db_lease'THEN RETURN scope-ARRAY['ttl_seconds']='{}'::jsonb AND (NOT(scope?'ttl_seconds')OR coalesce((r.scope_facts->>'issuance_ttl_seconds')::numeric,0)<=t);END IF;
 IF scope-ARRAY['ttl_seconds','prefixes','actions','region']<>'{}'::jsonb THEN RETURN false;END IF;
 IF scope?'region'AND scope->>'region'IS DISTINCT FROM r.scope_facts->>'region'THEN RETURN false;END IF;
 IF scope?'actions'AND(jsonb_typeof(scope->'actions')IS DISTINCT FROM'array'OR NOT(scope->'actions'<@coalesce(r.scope_facts->'actions','[]')))THEN RETURN false;END IF;
 IF scope?'prefixes'THEN IF jsonb_typeof(scope->'prefixes')IS DISTINCT FROM'array'THEN RETURN false;END IF;IF EXISTS(SELECT FROM jsonb_array_elements_text(scope->'prefixes')p WHERE p=''OR position('..'in p)>0 OR NOT EXISTS(SELECT FROM jsonb_array_elements_text(r.scope_facts->'prefixes')ceiling WHERE left(p,length(ceiling))=ceiling))THEN RETURN false;END IF;END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;
CREATE FUNCTION authz.provider_management_plan(p_hash text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE identity jsonb;o authz.provider_management_operations;r authz.provider_management_registrations;fingerprint text;authorized boolean:=false;
BEGIN
 IF NOT authz.provider_metadata_safe62(b)OR b-ARRAY['project_id','area_id','registration_id','action','idempotency_key','judgment','requested_scope','consumer_ids']<>'{}'::jsonb OR coalesce(length(b->>'idempotency_key'),0)NOT BETWEEN 1 AND 200 OR b->>'action'IS NULL OR b->>'action'NOT IN('issue','rotate','revoke','renew')THEN RAISE EXCEPTION 'invalid_management_plan';END IF;
 identity:=authz.provider_management_guard(p_hash,(b->>'project_id')::uuid,(b->>'area_id')::uuid,false);fingerprint:=encode(public.digest(b::text,'sha256'),'hex');PERFORM pg_advisory_xact_lock(hashtextextended((identity->>'actor_id')||'provider-management'||(b->>'idempotency_key'),0));
 SELECT * INTO o FROM authz.provider_management_operations WHERE actor_id=(identity->>'actor_id')::uuid AND idempotency_key=b->>'idempotency_key';
 IF o.id IS NOT NULL THEN IF o.fingerprint IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'original_operation_input_changed' USING ERRCODE='40001';END IF;RETURN authz.provider_management_view(o.id);END IF;
 SELECT * INTO r FROM authz.provider_management_registrations WHERE id=(b->>'registration_id')::uuid AND project_id=(b->>'project_id')::uuid AND area_id IS NOT DISTINCT FROM(b->>'area_id')::uuid;
 BEGIN PERFORM authz.provider_management_guard(p_hash,(b->>'project_id')::uuid,(b->>'area_id')::uuid,true);authorized:=r.id IS NOT NULL AND r.active AND authz.provider_management_scope_supported(r.id,coalesce(b->'requested_scope','{}'),CASE WHEN b?'consumer_ids' THEN ARRAY(SELECT jsonb_array_elements_text(b->'consumer_ids'))ELSE r.consumer_ids END);EXCEPTION WHEN insufficient_privilege THEN authorized:=false;END;
 INSERT INTO authz.provider_management_operations(project_id,area_id,actor_id,organization_id,original_client_id,registration_id,requested_action,expected_old_operation_id,expected_old_generation,idempotency_key,fingerprint,requested_scope,consumer_ids,scope_supported,judgment,state)VALUES((b->>'project_id')::uuid,(b->>'area_id')::uuid,(identity->>'actor_id')::uuid,(identity->>'organization_id')::uuid,(identity->>'client_id')::uuid,(b->>'registration_id')::uuid,b->>'action',r.active_operation_id,r.active_generation,b->>'idempotency_key',fingerprint,coalesce(b->'requested_scope','{}'),CASE WHEN b?'consumer_ids' THEN ARRAY(SELECT jsonb_array_elements_text(b->'consumer_ids'))ELSE coalesce(r.consumer_ids,'{}')END,coalesce(authz.provider_management_scope_supported(r.id,coalesce(b->'requested_scope','{}'),CASE WHEN b?'consumer_ids' THEN ARRAY(SELECT jsonb_array_elements_text(b->'consumer_ids'))ELSE r.consumer_ids END),false),coalesce(b->'judgment','{}'),CASE WHEN authorized THEN'planned'ELSE'planned_scope_needed'END)RETURNING * INTO o;
 INSERT INTO evidence.outbox(domain,aggregate_id,aggregate_revision,event_type,project_id,payload)VALUES('hufu',o.id,1,'provider.management.planned',o.project_id,jsonb_build_object('action',o.requested_action,'state',o.state));RETURN authz.provider_management_view(o.id);
END $$;
CREATE FUNCTION authz.provider_management_status(p_hash text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE o authz.provider_management_operations;identity jsonb;
BEGIN
 IF b-ARRAY['project_id','operation_id']<>'{}'::jsonb THEN RAISE EXCEPTION 'invalid_management_status';END IF;SELECT * INTO o FROM authz.provider_management_operations WHERE id=(b->>'operation_id')::uuid AND project_id=(b->>'project_id')::uuid;IF o.id IS NULL THEN RAISE EXCEPTION 'operation_scope_forbidden' USING ERRCODE='42501';END IF;identity:=authz.provider_management_guard(p_hash,o.project_id,o.area_id,false);IF o.actor_id IS DISTINCT FROM(identity->>'actor_id')::uuid THEN RAISE EXCEPTION 'operation_owner_forbidden' USING ERRCODE='42501';END IF;RETURN authz.provider_management_view(o.id);
END $$;
CREATE FUNCTION authz.provider_management_advance(p_hash text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE o authz.provider_management_operations;r authz.provider_management_registrations;s authz.provider_management_steps;identity jsonb;step text:=b->>'step';gen authz.credential_generations;n bigint;
BEGIN
 IF b-ARRAY['project_id','operation_id','expected_revision','step']<>'{}'::jsonb OR step IS NULL OR step NOT IN('issue','probe','stage','switch','revoke','renew','revoke_old')THEN RAISE EXCEPTION 'invalid_management_step';END IF;
 SELECT * INTO o FROM authz.provider_management_operations WHERE id=(b->>'operation_id')::uuid AND project_id=(b->>'project_id')::uuid;IF o.id IS NULL THEN RAISE EXCEPTION 'operation_forbidden' USING ERRCODE='42501';END IF;identity:=authz.provider_management_guard(p_hash,o.project_id,o.area_id,true);IF o.actor_id IS DISTINCT FROM(identity->>'actor_id')::uuid THEN RAISE EXCEPTION 'operation_owner_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO o FROM authz.provider_management_operations WHERE id=o.id FOR UPDATE;SELECT * INTO r FROM authz.provider_management_registrations WHERE id=o.registration_id FOR SHARE;
 IF NOT authz.provider_management_scope_supported(r.id,o.requested_scope,o.consumer_ids) OR r.id IS NULL OR NOT r.active OR r.project_id<>o.project_id OR r.area_id IS DISTINCT FROM o.area_id OR NOT(step=ANY(r.allowed_steps))THEN RAISE EXCEPTION 'registered_management_target_unavailable' USING ERRCODE='42501';END IF;
 SELECT * INTO s FROM authz.provider_management_steps WHERE operation_id=o.id ORDER BY step_no DESC LIMIT 1;
 IF s.state IN('intent','unknown')THEN RETURN authz.provider_management_view(o.id)||jsonb_build_object('state','original_effect_query_required','no_dispatch',true);END IF;
 IF o.state='complete'THEN RETURN authz.provider_management_view(o.id)||jsonb_build_object('no_dispatch',true);END IF;
 IF o.revision IS DISTINCT FROM(b->>'expected_revision')::bigint THEN RAISE EXCEPTION 'operation_revision_changed' USING ERRCODE='40001';END IF;
 SELECT * INTO gen FROM authz.credential_generations WHERE operation_id=o.id AND generation=o.generation FOR UPDATE;
 IF step='issue'AND o.requested_action IN('revoke','renew')THEN RAISE EXCEPTION 'existing_active_lease_required_no_new_issue';END IF;IF step='revoke_old'AND o.requested_action<>'rotate'THEN RAISE EXCEPTION 'not_rotation';END IF;
 IF step='issue'AND o.generation<>0 THEN RAISE EXCEPTION 'already_created_query_original' USING ERRCODE='40001';END IF;
 IF step='revoke_old'THEN SELECT * INTO gen FROM authz.credential_generations WHERE operation_id=o.expected_old_operation_id AND generation=o.expected_old_generation FOR UPDATE;END IF;IF step IN('revoke','renew')AND gen.generation IS NULL THEN SELECT * INTO gen FROM authz.credential_generations WHERE operation_id=o.expected_old_operation_id AND generation=o.expected_old_generation FOR UPDATE;END IF;
 IF step<>'issue'AND gen.generation IS NULL THEN RAISE EXCEPTION 'owned_generation_required';END IF;
 IF step='switch'AND EXISTS(SELECT FROM unnest(o.consumer_ids)c WHERE NOT EXISTS(SELECT FROM authz.consumer_generation_observations x WHERE x.operation_id=o.id AND x.generation=o.generation AND x.consumer_id=c AND x.state='probed'))THEN RAISE EXCEPTION 'consumer_active_observation_required';END IF;
 identity:=authz.provider_management_guard(p_hash,o.project_id,o.area_id,true);IF(identity->>'management_until')::timestamptz<=clock_timestamp()THEN RAISE EXCEPTION 'management_expired' USING ERRCODE='42501';END IF;
 n:=coalesce(s.step_no,0)+1;INSERT INTO authz.provider_management_steps(operation_id,step_no,kind,registration_revision,descriptor_hash,deadline,requested_by_client_id,credential_id,credential_epoch,principal_epoch,client_epoch,family_id,security_era)VALUES(o.id,n,step,r.revision,r.descriptor_hash,least(clock_timestamp()+interval '30 seconds',(identity->>'management_until')::timestamptz),(identity->>'client_id')::uuid,(identity->>'credential_id')::uuid,(SELECT epoch FROM authz.credentials WHERE id=(identity->>'credential_id')::uuid),(SELECT epoch FROM authz.principals WHERE id=(identity->>'actor_id')::uuid),(SELECT epoch FROM authz.clients WHERE id=(identity->>'client_id')::uuid),(SELECT family_id FROM authz.credentials WHERE id=(identity->>'credential_id')::uuid),(SELECT era FROM authz.security_state))RETURNING * INTO s;
 UPDATE authz.provider_management_operations SET revision=revision+1,state='effect_intent'WHERE id=o.id RETURNING * INTO o;INSERT INTO evidence.outbox(domain,aggregate_id,aggregate_revision,event_type,project_id,payload)VALUES('hufu',o.id,o.revision,'provider.management.intent',o.project_id,jsonb_build_object('step',step,'step_no',n));
 UPDATE authz.provider_management_steps SET execution_parameters=jsonb_build_object('state','dispatch_consumed','operation_id',o.id,'step_no',n,'step',step,'execution_token',s.execution_token,'registration_id',r.id,'registration_revision',r.revision,'descriptor_hash',r.descriptor_hash,'deadline',s.deadline,'generation',gen.generation,'target_generation_operation_id',gen.operation_id,'provider_identity',gen.provider_identity,'secret_ref',gen.secret_ref,'requested_scope',o.requested_scope,'consumer_ids',o.consumer_ids)WHERE operation_id=s.operation_id AND step_no=s.step_no RETURNING * INTO s;
 RETURN s.execution_parameters;
END $$;
CREATE FUNCTION authz.provider_management_authorize_effect(p_hash text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE s authz.provider_management_steps;o authz.provider_management_operations;r authz.provider_management_registrations;i jsonb;c authz.credentials;
BEGIN
 SELECT * INTO s FROM authz.provider_management_steps WHERE operation_id=(b->>'operation_id')::uuid AND step_no=(b->>'step_no')::bigint;
 SELECT * INTO o FROM authz.provider_management_operations WHERE id=s.operation_id;
 IF o.id IS NULL THEN RAISE EXCEPTION 'original_intent_required' USING ERRCODE='42501';END IF;
 i:=authz.provider_management_guard(p_hash,o.project_id,o.area_id,true);
 SELECT * INTO c FROM authz.credentials WHERE id=(i->>'credential_id')::uuid;
 SELECT * INTO s FROM authz.provider_management_steps WHERE operation_id=o.id AND step_no=s.step_no FOR UPDATE;
 SELECT * INTO r FROM authz.provider_management_registrations WHERE id=o.registration_id FOR SHARE;
 IF s.execution_parameters='{}'::jsonb OR b->'operation_id' IS DISTINCT FROM s.execution_parameters->'operation_id' OR b->'step_no' IS DISTINCT FROM s.execution_parameters->'step_no' OR b->'step' IS DISTINCT FROM s.execution_parameters->'step' OR b->'execution_token' IS DISTINCT FROM s.execution_parameters->'execution_token' OR b->'registration_id' IS DISTINCT FROM s.execution_parameters->'registration_id' OR b->'registration_revision' IS DISTINCT FROM s.execution_parameters->'registration_revision' OR b->'descriptor_hash' IS DISTINCT FROM s.execution_parameters->'descriptor_hash' OR b->'deadline' IS DISTINCT FROM s.execution_parameters->'deadline' OR b->'generation' IS DISTINCT FROM s.execution_parameters->'generation' OR b->'target_generation_operation_id' IS DISTINCT FROM s.execution_parameters->'target_generation_operation_id' OR b->'provider_identity' IS DISTINCT FROM s.execution_parameters->'provider_identity' OR b->'secret_ref' IS DISTINCT FROM s.execution_parameters->'secret_ref' OR b->'requested_scope' IS DISTINCT FROM s.execution_parameters->'requested_scope' OR b->'consumer_ids' IS DISTINCT FROM s.execution_parameters->'consumer_ids' THEN RAISE EXCEPTION 'original_execution_parameter_mismatch' USING ERRCODE='42501';END IF;
 IF s.state IS DISTINCT FROM'intent'OR s.effect_authorized_at IS NOT NULL OR s.deadline<=clock_timestamp()OR o.actor_id IS DISTINCT FROM(i->>'actor_id')::uuid OR s.credential_id IS DISTINCT FROM c.id OR s.credential_epoch IS DISTINCT FROM c.epoch OR s.principal_epoch IS DISTINCT FROM(SELECT epoch FROM authz.principals WHERE id=o.actor_id)OR s.client_epoch IS DISTINCT FROM(SELECT epoch FROM authz.clients WHERE id=c.client_id)OR s.family_id IS DISTINCT FROM c.family_id OR s.security_era IS DISTINCT FROM(SELECT era FROM authz.security_state)OR s.requested_by_client_id IS DISTINCT FROM c.client_id OR s.execution_token IS DISTINCT FROM(b->>'execution_token')::uuid OR b->>'step'IS DISTINCT FROM s.kind OR(b->>'registration_id')::uuid IS DISTINCT FROM r.id OR r.active IS DISTINCT FROM true OR r.revision IS DISTINCT FROM s.registration_revision OR r.descriptor_hash IS DISTINCT FROM s.descriptor_hash OR b->>'descriptor_hash'IS DISTINCT FROM s.descriptor_hash OR(b->>'registration_revision')::bigint IS DISTINCT FROM s.registration_revision OR NOT authz.provider_management_scope_supported(r.id,o.requested_scope,o.consumer_ids)THEN RAISE EXCEPTION 'current_original_effect_authority_required' USING ERRCODE='42501';END IF;
 IF b->'_validation_only'='true'::jsonb THEN RETURN jsonb_build_object('state','effect_validated','deadline',least(s.deadline,(i->>'management_until')::timestamptz),'execution',s.execution_parameters);END IF;
 UPDATE authz.provider_management_steps SET effect_authorized_at=clock_timestamp()WHERE operation_id=s.operation_id AND step_no=s.step_no;
 RETURN jsonb_build_object('state','effect_authorized','deadline',least(s.deadline,(i->>'management_until')::timestamptz),'execution',s.execution_parameters);
END $$;
CREATE FUNCTION authz.provider_management_reconcile(p_hash text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE view jsonb;s authz.provider_management_steps;o authz.provider_management_operations;r authz.provider_management_registrations;
BEGIN
 view:=authz.provider_management_status(p_hash,b);SELECT * INTO o FROM authz.provider_management_operations WHERE id=(b->>'operation_id')::uuid;SELECT * INTO s FROM authz.provider_management_steps WHERE operation_id=o.id ORDER BY step_no DESC LIMIT 1;SELECT * INTO r FROM authz.provider_management_registrations WHERE id=o.registration_id;
 RETURN view||jsonb_build_object('reconcile',CASE WHEN s.state IN('intent','unknown')THEN s.execution_parameters||jsonb_build_object('query_only',true)ELSE NULL END);
END $$;
CREATE FUNCTION authz.provider_management_receipt(b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE o authz.provider_management_operations;s authz.provider_management_steps;r authz.provider_management_registrations;v_receipt jsonb:=b->'receipt';kind text;consumer jsonb;
BEGIN
 IF authz.runtime_role()<>'hub2_hufu'OR NOT authz.provider_metadata_safe62(v_receipt)THEN RAISE EXCEPTION 'unsafe_or_untrusted_receipt' USING ERRCODE='42501';END IF;SELECT * INTO s FROM authz.provider_management_steps WHERE operation_id=(b->>'operation_id')::uuid AND step_no=(b->>'step_no')::bigint FOR UPDATE;SELECT * INTO o FROM authz.provider_management_operations WHERE id=s.operation_id FOR UPDATE;SELECT * INTO r FROM authz.provider_management_registrations WHERE id=o.registration_id;
 IF s.state IN('known_succeeded','known_failed')AND s.execution_token IS NOT DISTINCT FROM(b->>'execution_token')::uuid AND s.descriptor_hash IS NOT DISTINCT FROM b->>'descriptor_hash'AND s.registration_revision IS NOT DISTINCT FROM(b->>'registration_revision')::bigint AND s.receipt IS NOT DISTINCT FROM v_receipt THEN RETURN authz.provider_management_view(o.id);END IF;
 IF s.operation_id IS NULL OR o.id IS NULL OR r.id IS NULL OR s.execution_token IS DISTINCT FROM(b->>'execution_token')::uuid OR s.descriptor_hash IS DISTINCT FROM b->>'descriptor_hash'OR s.registration_revision IS DISTINCT FROM(b->>'registration_revision')::bigint OR s.state NOT IN('intent','unknown')OR v_receipt->>'outcome'IS NULL OR v_receipt->>'outcome'NOT IN('known_succeeded','known_failed','unknown')THEN RAISE EXCEPTION 'original_effect_receipt_mismatch' USING ERRCODE='42501';END IF;
 IF v_receipt->>'outcome'='known_failed'AND s.effect_authorized_at IS NOT NULL THEN RAISE EXCEPTION 'authorized_effect_requires_known_or_unknown_actual_outcome' USING ERRCODE='42501';END IF;
 UPDATE authz.provider_management_steps SET state=v_receipt->>'outcome',receipt=v_receipt WHERE operation_id=o.id AND step_no=s.step_no;
 IF v_receipt->>'outcome'='known_succeeded'THEN
  IF s.kind='issue'THEN IF NOT(v_receipt?&ARRAY['provider_identity','secret_ref'])THEN RAISE EXCEPTION 'generation_identity_required';END IF;INSERT INTO authz.credential_generations VALUES(o.id,o.generation+1,r.id,v_receipt->'provider_identity',v_receipt->>'secret_ref',(v_receipt->>'expires_at')::timestamptz,'created');UPDATE authz.provider_management_operations SET generation=generation+1,state='new_created'WHERE id=o.id;
  ELSIF s.kind IN('stage','probe')THEN
   consumer:=v_receipt->'consumer_observation';IF consumer IS NOT NULL THEN IF NOT(consumer->>'consumer_id'=ANY(o.consumer_ids))OR consumer->>'state'NOT IN('staged','probed','active_verified')OR consumer->'positive_probe'IS NULL OR consumer->'cross_scope_probe'IS NULL THEN RAISE EXCEPTION 'registered_consumer_observation_required';END IF;INSERT INTO authz.consumer_generation_observations VALUES(o.id,o.generation,consumer->>'consumer_id',consumer->>'state',consumer->>'config_revision',consumer->'positive_probe',consumer->'cross_scope_probe',clock_timestamp())ON CONFLICT(operation_id,generation,consumer_id)DO UPDATE SET state=excluded.state,config_revision=excluded.config_revision,positive_probe=excluded.positive_probe,cross_scope_probe=excluded.cross_scope_probe,observed_at=excluded.observed_at;END IF;UPDATE authz.provider_management_operations SET state=CASE WHEN s.kind='probe'THEN'new_probe_passed'ELSE'consumer_staged'END WHERE id=o.id;
  ELSIF s.kind='switch'THEN consumer:=v_receipt->'consumer_observation';IF consumer IS NULL OR consumer->>'state'IS DISTINCT FROM'active_verified'OR NOT(consumer->>'consumer_id'=ANY(o.consumer_ids))OR consumer->'positive_probe'IS DISTINCT FROM'{"verified":true}'::jsonb OR consumer->'cross_scope_probe'IS DISTINCT FROM'{"denied":true}'::jsonb THEN RAISE EXCEPTION 'actual_active_consumer_observation_required';END IF;UPDATE authz.consumer_generation_observations SET state='active_verified',config_revision=consumer->>'config_revision',observed_at=clock_timestamp()WHERE operation_id=o.id AND generation=o.generation AND consumer_id=consumer->>'consumer_id';IF EXISTS(SELECT FROM unnest(o.consumer_ids)c WHERE NOT EXISTS(SELECT FROM authz.consumer_generation_observations x WHERE x.operation_id=o.id AND x.generation=o.generation AND x.consumer_id=c AND x.state='active_verified'))THEN RAISE EXCEPTION 'all_registered_consumer_observations_required';END IF;IF r.active_operation_id IS DISTINCT FROM o.expected_old_operation_id OR r.active_generation IS DISTINCT FROM o.expected_old_generation THEN RAISE EXCEPTION 'active_generation_CAS_changed' USING ERRCODE='40001';END IF;UPDATE authz.provider_management_registrations SET active_operation_id=o.id,active_generation=o.generation WHERE id=r.id;UPDATE authz.credential_generations SET state='active'WHERE operation_id=o.id AND generation=o.generation;UPDATE authz.provider_management_operations SET state=CASE WHEN requested_action='rotate'THEN'active_switched'ELSE'complete'END WHERE id=o.id;
  ELSIF s.kind='renew'THEN UPDATE authz.credential_generations SET expires_at=(v_receipt->>'expires_at')::timestamptz WHERE operation_id=CASE WHEN o.generation=0 THEN o.expected_old_operation_id ELSE o.id END AND generation=CASE WHEN o.generation=0 THEN o.expected_old_generation ELSE o.generation END;UPDATE authz.provider_management_operations SET state='complete'WHERE id=o.id;
  ELSIF s.kind IN('revoke','revoke_old')THEN kind:=v_receipt->>'closure_kind';IF kind IS NULL OR kind NOT IN('provider_revoked_verified','expired_verified','platform_denied_only')THEN RAISE EXCEPTION 'closure_fact_kind_required';END IF;UPDATE authz.credential_generations SET state=kind WHERE operation_id=CASE WHEN s.kind='revoke_old'OR o.generation=0 THEN o.expected_old_operation_id ELSE o.id END AND generation=CASE WHEN s.kind='revoke_old'OR o.generation=0 THEN o.expected_old_generation ELSE o.generation END;UPDATE authz.provider_management_operations SET state=CASE WHEN kind='provider_revoked_verified'THEN'complete'ELSE kind END WHERE id=o.id;
  END IF;
 ELSE UPDATE authz.provider_management_operations SET state=v_receipt->>'outcome'WHERE id=o.id;END IF;
 UPDATE authz.provider_management_operations SET revision=revision+1 WHERE id=o.id RETURNING * INTO o;INSERT INTO evidence.outbox(domain,aggregate_id,aggregate_revision,event_type,project_id,payload)VALUES('hufu',o.id,o.revision,'provider.management.receipt',o.project_id,jsonb_build_object('step',s.kind,'state',o.state));RETURN authz.provider_management_view(o.id);
END $$;
REVOKE ALL ON FUNCTION authz.provider_management_scope_supported(uuid,jsonb,text[]),authz.provider_management_authorize_effect(text,jsonb),authz.provider_management_guard(text,uuid,uuid,boolean),authz.provider_management_view(uuid),authz.provider_management_plan(text,jsonb),authz.provider_management_status(text,jsonb),authz.provider_management_advance(text,jsonb),authz.provider_management_reconcile(text,jsonb),authz.provider_management_receipt(jsonb)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authz.provider_management_authorize_effect(text,jsonb),authz.provider_management_plan(text,jsonb),authz.provider_management_status(text,jsonb),authz.provider_management_advance(text,jsonb),authz.provider_management_reconcile(text,jsonb),authz.provider_management_receipt(jsonb)TO hub2_hufu;
RESET ROLE;
